1	import { describe, expect, it } from 'vitest';
2	import {
3		ANGULAR_SUPER_PRODUCTIVITY_APP,
4		ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS,
5		ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_CHAIN,
6		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_CONSOLE_ERRORS,
7		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_FAILED_REQUESTS,
8		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_HOST_TAG_CORRECTION,
9		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_JOURNEY,
10		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_KEY_ORDER_CORRECTION,
11		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_LANE_SEAMS,
12		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MEASURED_STYLE_DIFFERENCES,
13		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_REGRESSION,
14		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE,
15		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE,
16		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SEAMS,
17		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER,
18		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SETTINGS,
19		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES,
20		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE,
21		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TIME_TRACKING_REANCHOR,
22		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_DEGRADATION_CAUSE,
23		WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TYPEFACE_PROBE,
24	} from '../../core/src/receipts/witness-angular-super-productivity.ts';
25	import { angularSuperProductivityWitnessSpec } from '../src/witness/real-app-run.ts';
26	
27	const spec = angularSuperProductivityWitnessSpec();
28	const journey = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_JOURNEY;
29	
30	describe('the Super Productivity journey wiring', () => {
31		it('is the Angular vertical the receipt schema names, on the roots it binds', () => {
32			expect(spec.app).toBe(ANGULAR_SUPER_PRODUCTIVITY_APP);
33			expect(spec.framework).toBe('angular');
34			const bound = Object.fromEntries(
35				ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS.map((receipt) => [
36					receipt.lane,
37					receipt.canonicalRoot,
38				]),
39			);
40			// The lane roots the spec serves must END with the canonical output root
41			// the schema pins for that lane; serving a sibling would be serving one
42			// build rather than the lane the bound record describes.
43			expect(spec.sources.baseline.endsWith(bound.baseline!)).toBe(true);
44			expect(spec.sources.migrated.endsWith(bound.migrated!)).toBe(true);
45		});
46	
47		it('binds the migrated build record by the sha256 of its exact bytes', () => {
48			const migrated = ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS.find(
49				(receipt) => receipt.lane === 'migrated',
50			);
51			expect(spec.canonicalBinding).toBe('file-sha256');
52			expect(spec.canonicalReceipt).toBe(migrated!.path);
53			expect(spec.canonicalDigest).toBe(migrated!.sha256);
54			// The record it binds has to be the end of the migrated lane's supersession
55			// chain, or the proof would be served from a build the chain says was
56			// contradicted.
57			expect(spec.canonicalReceipt).toBe(
58				ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_CHAIN.at(-1)!.record,
59			);
60			expect(ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_CHAIN.at(-1)!.contradictedBy).toBeNull();
61		});
62	
63		it('deep-links the declared work-view route rather than the bare document', () => {
64			// Measured: the bare document records its navigation as `#/`, which the
65			// router resolves through its `**` route. The schema refuses a recorded
66			// route the application does not declare, and `/` is not one of the nine.
67			expect(spec.initialRoute).toBe(journey.initialRoute);
68			expect(journey.initialRoute).toBe('/#/work-view');
69			expect(WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE.known).toContain('/work-view');
70			expect(journey.initialRoute.startsWith(`/${WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE.prefix}`)).toBe(
71				true,
72			);
73			// The deep-linked document and the reload leg (e) performs: two, exactly.
74			expect(journey.navigations).toBe(2);
75		});
76	
77		it('measures against a stated viewport, because it claims scroll absence', () => {
78			expect(spec.viewport).toEqual({ width: 1280, height: 900 });
79			expect(spec.viewport).toEqual(journey.viewport);
80		});
81	
82		it('declares the exact probe list the schema checks, in the schema order', () => {
83			expect(spec.renderedStyleProbes).toBe(WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES);
84			// The typeface reading is anchored on a probe that is actually measured,
85			// and on one the two lanes agree about — the reasoning is beside the
86			// constant, and this is the half of it a test can hold.
87			const labels = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_PROBES.map((probe) => probe.label);
