94	/** Every file of an emitted artifact, addressed exactly as the u22 record does. */
95	async function inventoryOf(rootDirectory: string): Promise<InventoryEntry[]> {
96		const entries: InventoryEntry[] = [];
97		for (const file of await files(rootDirectory)) {
98			const bytes = await readFile(file);
99			entries.push({
100				path: relative(rootDirectory, file),
101				sha256: sha256(bytes),
102				bytes: bytes.length,
103			});
