108	/** The pinned migrated build record, re-read rather than restated. */
109	async function migratedLaneRecord(): Promise<{
110		inventory: InventoryEntry[];
111		inventorySha256: string;
112	}> {
113		const pinned = ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.find(
114			(receipt) => receipt.lane === 'migrated',
115		);
116		if (pinned === undefined) throw new Error('TinyTranslator migrated lane binding is absent');
117		const bytes = await readFile(join(root, pinned.path));
118		if (sha256(bytes) !== pinned.sha256)
119			throw new Error(`TinyTranslator bound build receipt bytes drifted: ${pinned.path}`);
120		const record = JSON.parse(bytes.toString('utf8')) as {
121			inventory?: InventoryEntry[];
122			determinism?: { inventorySha256?: string };
123		};
124		const inventory = record.inventory;
125		const inventorySha256 = record.determinism?.inventorySha256;
126		if (!Array.isArray(inventory) || typeof inventorySha256 !== 'string')
127			throw new Error('TinyTranslator migrated lane record publishes no inventory to verify');
128		return { inventory, inventorySha256 };
