131	/**
132	 * The digest the u22 record computed over its own inventory: the pretty-printed
133	 * JSON array with a trailing newline, exactly as the recording flow wrote it.
134	 * Recomputing it here rather than accepting the record's own number is what
135	 * makes the comparison a check instead of a restatement.
136	 */
137	function inventoryDigest(inventory: readonly InventoryEntry[]): string {
138		return sha256(`${JSON.stringify(inventory, null, 2)}\n`);
139	}
140	
141	async function run(command: string, args: readonly string[], cwd: string): Promise<void> {
142		await new Promise<void>((settle, fail) => {
143			const child = spawn(command, [...args], {
144				cwd,
145				stdio: 'ignore',
146				env: {
