242	/**
243	 * Byte mutation on the migrated build.
244	 *
245	 * The seam is the visible label of the control that opens the file picker: a
246	 * string a reader sees, asserted exactly by the journey on the create-project
247	 * route, and the name of the very mechanism this vertical exists to exercise.
248	 * The uniqueness demanded here is the corpus discipline — exactly one served
249	 * module may carry it, exactly once — so overwriting it in place cannot be
250	 * absorbed by a second copy elsewhere in the bundle.
251	 */
252	async function semanticMutation(
253		laneRoot: string,
254		behaviorDigest: string,
255	): Promise<WitnessAngularTinyTranslatorMutation> {
256		const expected = Buffer.from(TINY_TRANSLATOR_MUTATION_SEAM);
257		const candidates: Array<{ path: string; offset: number }> = [];
258		for (const path of await files(laneRoot)) {
259			const bytes = await readFile(path);
260			const offset = bytes.indexOf(expected);
261			if (offset < 0) continue;
262			if (bytes.lastIndexOf(expected) !== offset)
263				throw new Error('TinyTranslator semantic seam is not unique within its file');
264			candidates.push({ path, offset });
265		}
266		const target = candidates[0];
267		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
268			throw new Error('TinyTranslator semantic seam is not a single served module');
269		const before = await readFile(target.path);
270		const mutated = Buffer.from(before);
271		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
272		const beforeSha256 = sha256(before);
273		const mutatedSha256 = sha256(mutated);
274		let intendedFailure = false;
275		try {
276			await writeFile(target.path, mutated);
277			try {
278				await executeAngularTinyTranslatorWitnessRun({
279					lane: 'migrated',
280					pass: 1,
281					laneRoot,
282					receiptRoot: join(stageRoot, 'mutation-receipt'),
283				});
284			} catch (error) {
285				const message = error instanceof Error ? error.message : String(error);
286				intendedFailure = message.includes(TINY_TRANSLATOR_MUTATION_SEAM);
287			}
288		} finally {
289			await writeFile(target.path, before);
290		}
291		const afterRestoreSha256 = sha256(await readFile(target.path));
292		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
293			throw new Error('TinyTranslator semantic mutation was not exact red and byte-restored');
294		const restored = (await executeAngularTinyTranslatorWitnessRun({
295			lane: 'migrated',
296			pass: 1,
297			laneRoot,
298			receiptRoot: join(stageRoot, 'restoration-receipt'),
299		})) as WitnessAngularTinyTranslatorRun;
300		const restoredBehaviorDigest = witnessAngularTinyTranslatorBehaviorDigest(restored);
301		if (restoredBehaviorDigest !== behaviorDigest)
302			throw new Error('TinyTranslator restored browser behavior differs');
303		return {
304			failure: 'witness-semantic-assertion',
305			intendedFailure: true,
306			lane: 'migrated',
307			seam: TINY_TRANSLATOR_MUTATION_SEAM,
308			path: relative(laneRoot, target.path),
309			offset: target.offset,
310			beforeSha256,
311			mutatedSha256,
312			afterRestoreSha256,
313			restoredByteIdentically: true,
314			restoredRun: 'pass',
315			restoredBehaviorDigest,
316		};
317	}
318	
319	/**
320	 * The nonclaims this proof publishes. Each one names something a reader could
321	 * otherwise assume from the rest of the receipt and states plainly that it is
322	 * not established here.
323	 */
324	export const WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS: readonly string[] = Object.freeze([
325		'This is one Angular lineage under direct Witness and does not establish generic Angular, Angular CLI 1.5, `.angular-cli.json` workspaces, or `@angular-devkit/build-angular:browser` support.',
326		'The Angular lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
327		'There is no backend and nothing was stubbed or seeded by the harness. The project the journey works on is created by the application itself, from a file this proof hands its own file input, and everything it keeps it keeps in browser local storage.',
328		'The translation file handed to the page is synthetic and authored for this proof. It carries no upstream project’s strings and no third party’s translated content, and it is bound by name, length and digest so a journey cannot quietly load a different one.',
329		'The file the page produced is read back by name, byte length and digest, and its content is asserted rather than published: a produced translation file is the application’s data, not this receipt’s.',
330		'Neither lane ends up with the Material Icons glyphs, and since the migrated lane was rebuilt without the builder’s font inliner they fail to get them the same way: both request the stylesheet the application links, both are answered inside the browser context so that nothing leaves the machine, and neither receives a `@font-face` rule. The degradation is measured per lane and recorded rather than masked, and it is not a regression of the migration.',
331		'The migrated lane is built with `optimization.fonts.inline: false`, and the two builds behind the served root were measured making no non-loopback connection attempt at all. That is a fact about those build processes, established by an in-process guard; it is not a claim that the machine was offline, and it establishes nothing about any request this application makes that the guard did not see.',
332		'Two of the four rendered-appearance probes are declared to differ across the eleven-major lift and are checked in both directions — a probe outside the declaration that differs fails the run, and a declared difference that stopped being real fails it too.',
333		'Byte parity across the lanes is not claimed and is recorded separately by the bound build receipts; eleven majors of bundler produce different file names and different byte counts by construction.',
334		'Neither build ships a service worker, and BOTH attempt to register one. The application registers at the literal `%BASE_HREF%ngsw-worker.js` — a placeholder upstream substitutes in a separate npm script that `ng build` never runs — and the request is answered 400 in both lanes. It is an era defect that survives the migration: the migration did not introduce it and no capability here repaired it, and it is recorded rather than suppressed.',
335		'Locality is process-scoped and does not establish operating-system-wide isolation.',
336		'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
337	]);
338	
339	async function bindCanonicalReceipts(): Promise<
340		WitnessAngularTinyTranslatorReceipt['canonicalReceipts']
341	> {
342		return await Promise.all(
343			ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.map(async (pinned) => {
344				const bytes = await readFile(join(root, pinned.path));
345				const value = JSON.parse(bytes.toString('utf8')) as {
346					schemaVersion?: unknown;
347					digest?: unknown;
348				};
349				if (
350					value.schemaVersion !== pinned.schemaVersion ||
351					value.digest !== pinned.digest ||
352					sha256(bytes) !== pinned.sha256
353				)
354					throw new Error(
355						`TinyTranslator bound build receipt identity differs: ${pinned.path}`,
356					);
357				return { ...pinned };
358			}),
359		);
360	}
361	
362	export async function runWitnessAngularTinyTranslator(): Promise<WitnessAngularTinyTranslatorReceipt> {
363		if (
364			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
365			process.env.NPM_CONFIG_OFFLINE !== 'true'
366		)
367			throw new Error('TinyTranslator Witness requires dual offline controls');
368		if (await exists(witnessEvidence))
369			throw new Error('TinyTranslator Witness output collision');
370		const provenance = await verifyLinkedWitnessProvenance(root);
371		const canonicalReceipts = await bindCanonicalReceipts();
372		const lanes = await stageInputs();
373		const runs = await executeRuns(lanes);
374		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
375		const baseline = runs.find((entry) => entry.lane === 'baseline')!;
376		const migrated = runs.find((entry) => entry.lane === 'migrated')!;
377		const artifacts = join(fixtureEvidence, 'witness-artifacts');
378		await mkdir(artifacts, { recursive: true });
379		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
380			flag: 'wx',
381		});
382		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
383			flag: 'wx',
384		});
385		const receipt: WitnessAngularTinyTranslatorReceipt = {
386			schemaVersion: WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
387			result: 'pass',
388			fixture: ANGULAR_TINY_TRANSLATOR_FIXTURE,
389			source: ANGULAR_TINY_TRANSLATOR_SOURCE,
390			provenance,
391			canonicalReceipts,
392			runs,
393			mutation,
394			consoleErrors: {
395				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.baseline],
396				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.migrated],
397			},
398			failedRequests: {
399				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.baseline],
400				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.migrated],
401			},
402			mockedSeams: {
403				baseline: [...baseline.mockedNonLoopbackSeams.category],
404				migrated: [...migrated.mockedNonLoopbackSeams.category],
405			},
406			fontSeamDifference: WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
407			serviceWorkerAttempt: WITNESS_ANGULAR_TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
408			migratedLaneChain: ANGULAR_TINY_TRANSLATOR_MIGRATED_LANE_CHAIN,
409			migrationFindings: WITNESS_ANGULAR_TINY_TRANSLATOR_MIGRATION_FINDINGS,
410			amendments: WITNESS_ANGULAR_TINY_TRANSLATOR_RECORDED_AMENDMENTS,
411			/**
412			 * The arbitration outcome, read out of the runs rather than declared beside
413			 * them: the obligation the build lanes handed this proof is the one the
414			 * schema publishes, and the numbers are the parse both lanes measured.
415			 */
416			fileReaderArbitration: {
417				state: 'arbitrated-declared-difference',
418				obligation: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS.journeyObligations[0]!,
419				outcome: 'identical-parse-in-both-lanes',
420				parsedUnits: baseline.applicationJourney.fileReaderParity.parsedUnits,
421				parsedDigest: baseline.applicationJourney.fileReaderParity.parsedDigest,
422				inBehaviorDigest: true,
423			},
424			matIconDegradations: {
425				baseline: baseline.applicationJourney.matIcon,
426				migrated: migrated.applicationJourney.matIcon,
427			},
428			renderedStyleParity: {
429				state: 'measured-resolved-styles-with-declared-differences',
430				probes: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES.length,
431				declaredDifferences: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
432				otherProbesAgree: true,
433			},
434			fileInput: {
435				surfaces: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
436				fixture: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
437				rule: WITNESS_FILE_INPUT_LOAD_RULE,
438			},
439			downloads: {
440				surface: WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
441				rule: WITNESS_DOWNLOAD_CAPTURE_RULE,
442				captured: runs.map((entry) => ({
443					lane: entry.lane,
444					pass: entry.pass,
445					files: [...entry.downloadCaptures.captured],
446				})),
447			},
448			persistence: {
449				store: 'browser-local-storage',
450				backend: 'none',
451				stubbed: false,
452				survivesOnlineReload: true,
453			},
454			routeShape: WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
455			scrollAbsence: runs[0]!.scrollAbsence,
456			accommodations: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
457			readiness: {
458				angularLineage: { ready: 1, total: 4, counted: false },
459				overall: { ready: 3, total: 12 },
460			},
461			locality: {
462				mode: 'offline',
463				successfulNonLoopback: 0,
464				osWideIsolation: false,
465				mockedNonLoopbackSeams: migrated.mockedNonLoopbackSeams.category.length,
466			},
467			nonclaims: [...WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS],
468			integrity: { algorithm: 'sha256', canonicalDigest: '' },
469		};
470		receipt.integrity.canonicalDigest = witnessAngularTinyTranslatorDigest(receipt);
471		parseWitnessAngularTinyTranslatorReceipt(receipt);
472		await mkdir(witnessEvidence, { recursive: true });
473		const canonical = canonicalize(receipt);
474		/**
475		 * The companion is rendered from the receipt as PUBLISHED rather than from
476		 * the object in memory: canonicalization sorts keys, so a companion rendered
477		 * from the in-memory object would disagree with the same companion rendered
478		 * from the file, and `verify` — which only ever has the file — would be
479		 * right to reject it.
480		 */
481		const published = parseWitnessAngularTinyTranslatorReceipt(JSON.parse(canonical));
482		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonical}\n`, { flag: 'wx' });
483		await writeFile(
484			join(witnessEvidence, 'receipt.md'),
485			renderWitnessAngularTinyTranslatorReceipt(published),
486			{ flag: 'wx' },
487		);
488		return published;
489	}
490	
491	export async function verifyWitnessAngularTinyTranslator(
492		output = witnessEvidence,
493	): Promise<WitnessAngularTinyTranslatorReceipt> {
494		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
495		const receipt = parseWitnessAngularTinyTranslatorReceipt(
496			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
497		);
498		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
499			throw new Error('TinyTranslator linked Witness provenance differs');
500		for (const bound of receipt.canonicalReceipts)
501			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
502				throw new Error(`TinyTranslator bound build receipt bytes drifted: ${bound.path}`);
503		if (
504			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
505			renderWitnessAngularTinyTranslatorReceipt(receipt)
506		)
507			throw new Error('TinyTranslator human Witness receipt differs');
508		const serialized = canonicalize(receipt);
509		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
510			throw new Error('TinyTranslator receipt leaks host identity');
511		return receipt;
512	}
513	
514	export async function main(args = process.argv.slice(2)): Promise<void> {
515		const publishIndex = args.indexOf('--publish');
516		const verifyIndex = args.indexOf('--verify');
517		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
518			const output = resolve(root, args[publishIndex + 1]!);
519			if (output !== witnessEvidence) throw new Error('TinyTranslator publish path differs');
520			const receipt = await runWitnessAngularTinyTranslator();
521			process.stdout.write(
522				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
523			);
524			return;
525		}
526		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
527			const receipt = await verifyWitnessAngularTinyTranslator(
528				resolve(root, args[verifyIndex + 1]!),
529			);
530			process.stdout.write(
531				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
532			);
533			return;
534		}
535		throw new Error(
536			'TinyTranslator Witness runner requires --run-twice --publish <dir> or --verify <dir>',
537		);
538	}
539	
540	if (basename(process.argv[1] ?? '') === 'angular-tiny-translator-run.ts')
541		main().catch((error: unknown) => {
542			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
543			process.exitCode = 1;
544		});
