1	/**
2	 * The Super Productivity leg-(d) THEME-CONTROL calibration driver.
3	 *
4	 * u20c2l established the project-switch spine is green and that the witness
5	 * PageHandle cannot drive a native `input[type=color]`, so the save-side palette
6	 * shift it produces is unprovable. This driver answers the one question that
7	 * ruling left open: is there a CLICK-driveable theme control whose driven change
8	 * provably shifts a MEASURED style variable, on BOTH lanes.
9	 *
10	 * The two candidates are the project theme form's own `isAutoContrast` checkbox
11	 * and its `huePrimary` mat-select. It navigates to the project settings, expands
12	 * the theme section, probes the palette and contrast custom properties, drives
13	 * each control by a real click, saves, and re-probes — printing every reading
14	 * (including the refusals, which are the measurement when a candidate is wrong).
15	 *
16	 * It publishes nothing, asserts nothing of its own, and is not part of any
17	 * receipt. Its only output is stdout.
18	 */
19	
20	import { basename, join, resolve } from 'pathe';
21	import { box, runBoxes } from '@async/witness';
22	import { joinURL } from 'ufo';
23	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
24	import { witnessNodeFileSystem } from '../witness/node-filesystem.ts';
25	import { createPlaywrightWitnessHost } from '../witness/playwright-host.ts';
26	import { startStaticServer } from '../witness/real-app-run.ts';
27	
28	const root = resolve(import.meta.dirname, '../../../..');
29	
30	const laneRoots = {
31		baseline: join(
32			root,
33			'.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
34		),
35		migrated: join(root, '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-25'),
36	} as const;
37	
38	const VIEWPORT = { width: 1280, height: 900 } as const;
39	const INITIAL_ROUTE = '/#/work-view';
40	
41	/**
42	 * The palette and contrast custom properties the driven change is measured
43	 * against. The base `--palette-primary-500` moves only with the primary COLOR
44	 * (the undriveable color input), so it is the control reading. The
45	 * `--palette-primary-contrast-*` variables move with `setAutoContrastEnabled`
46	 * and `setContrastColorThresholdPrimary(huePrimary)`, which are exactly what the
47	 * checkbox and the select drive.
48	 */
49	const PALETTE_PROPS = [
50		'--palette-primary-500',
51		'--palette-primary-contrast-50',
52		'--palette-primary-contrast-100',
53		'--palette-primary-contrast-200',
54		'--palette-primary-contrast-300',
55		'--palette-primary-contrast-400',
56		'--palette-primary-contrast-500',
57		'--palette-primary-contrast-600',
58		'--palette-primary-contrast-700',
59		'--palette-primary-contrast-900',
60	];
61	
62	export async function calibrateAngularSuperProductivityTheme(
63		lane: 'baseline' | 'migrated',
64	): Promise<void> {
65		const laneRoot = laneRoots[lane];
66		const receiptDir = join(
67			root,
68			'.versionless/stage/witness-angular-super-productivity-theme-calibrate',
69			lane,
70		);
71		const staticServer = await startStaticServer(laneRoot, { profile: 'current-witness' });
72		const host = createPlaywrightWitnessHost({
73			chromiumExecutable: join(
74				root,
75				'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
76			),
77			contextProfile: 'current-witness',
78			viewport: VIEWPORT,
79			indexedDb: 'read-keys',
80			transport: async () => ({
81				action: 'fulfill',
82				status: 200,
83				contentType: 'text/css',
84				body: Buffer.alloc(0),
85			}),
86		});
87		const out: Record<string, unknown> = {};
88		const definition = box(`super-productivity-theme-calibrate-${lane}`, async (context) => {
89			const page = await context.browser.visit(joinURL(staticServer.origin, INITIAL_ROUTE));
90			const wait = (ms: number): Promise<void> =>
91				new Promise<void>((settle) => void setTimeout(settle, ms));
92			const readPalette = async (): Promise<unknown> =>
93				host
94					.renderedStyles([{ label: 'body', selector: 'body', properties: [...PALETTE_PROPS] }])
95					.then(
96						(probes) => probes[0]?.properties ?? null,
97						(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
98					);
99			const readCount = async (selector: string): Promise<number | string> => {
100				try {
101					await context.expect.page.count(page, selector, 0);
102					return 0;
103				} catch (error: unknown) {
104					const line = (error instanceof Error ? error.message : String(error))
105						.split('\n')[0]!
106						.trim();
107					const m = line.match(/observed (\d+)/);
108					return m ? Number(m[1]) : line;
109				}
110			};
111			const clickIfPresent = async (selector: string): Promise<string> => {
112				try {
113					await page.click(selector, { timeoutMs: 4_000 });
114					return 'clicked';
115				} catch (error: unknown) {
116					return `failed: ${(error instanceof Error ? error.message : String(error)).split('\n')[0]!}`;
117				}
118			};
119	
120			const readCurrentTitle = async (): Promise<unknown> =>
121				host
122					.groupedText({
123						group: 'main-header',
124						name: '.current-project-title',
125						item: '.current-project-title',
126					} as const)
127					.then(
128						(g) => g.map((x) => x.name),
129						(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
130					);
131			const readProjectTitles = async (): Promise<unknown> =>
132				host
133					.groupedText({
134						group: 'side-nav .project',
135						name: 'button[mat-menu-item]',
136						item: 'button[mat-menu-item]',
137					} as const)
138					.then(
139						(g) => g.map((x) => x.name),
140						(e: unknown) => `refused: ${e instanceof Error ? e.message : String(e)}`,
141					);
142			await page.trackEvents('click', 'keydown');
143	
144			// (d.1) Project-switch spine: create a second project through the side-nav
145			// addProject() dialog and switch to it.
146			out['current-title-before'] = await readCurrentTitle();
147			out['project-titles-before'] = await readProjectTitles();
148			out['project-count-before'] = await readCount('side-nav .project');
149			out['add-clicked'] = await clickIfPresent('section.projects > button[mat-menu-item]');
150			await wait(1_200);
151			out['dialog-count'] = await readCount('dialog-create-project');
152			out['title-typed'] = await (async (): Promise<string> => {
153				try {
154					await page.type('dialog-create-project input:not([type=color])', 'Witness leg-d project', {
155						redact: false,
156						timeoutMs: 4_000,
157					});
158					return 'typed';
159				} catch (error: unknown) {
160					return `failed: ${(error instanceof Error ? error.message : String(error)).split('\n')[0]!}`;
161				}
162			})();
163			await wait(400);
164			out['dialog-save-clicked'] = await clickIfPresent('dialog-create-project button[type=submit]');
165			await wait(1_500);
166			out['project-count-after'] = await readCount('side-nav .project');
167			out['project-titles-after'] = await readProjectTitles();
168			out['switch-clicked'] = await clickIfPresent(
169				'side-nav .project:nth-of-type(2) > button[mat-menu-item]',
170			);
171			await wait(1_500);
172			out['current-title-after-switch'] = await readCurrentTitle();
173	
174			// Navigate to the current project's settings via the header control.
175			out['settings-nav-clicked'] = await clickIfPresent('main-header .project-settings-btn');
176			await wait(1_500);
177			out['route-after-settings-nav'] = 'see navigations';
178			out['config-section-count'] = await readCount('section.config-section');
179			// Expand the theme config-section (the 2nd).
180			out['expand-clicked'] = await clickIfPresent(
181				'section.config-section:nth-of-type(2) .collapsible-title',
182			);
183			await wait(1_200);
184	
185			const theme = 'section.config-section:nth-of-type(2)';
186			out['checkbox-count'] = await readCount(`${theme} mat-checkbox`);
187			out['select-count-before'] = await readCount(`${theme} mat-select`);
188			out['color-input-count'] = await readCount(`${theme} input[type=color]`);
189			out['submit-count'] = await readCount(`${theme} .submit-button`);
190			out['palette-before'] = await readPalette();
191	
192			// (candidate A) The isAutoContrast checkbox. Default true; a click toggles
193			// it false, which flips `setAutoContrastEnabled` and applies the hue
194			// thresholds on save.
195			out['autocontrast-click'] = await clickIfPresent(`${theme} mat-checkbox label`);
196			await wait(500);
197			out['palette-after-autocontrast-toggle-preSave'] = await readPalette();
198			out['autocontrast-save'] = await clickIfPresent(`${theme} .submit-button`);
199			await wait(1_800);
200			out['palette-after-autocontrast-save'] = await readPalette();
201			out['select-count-after-uncheck'] = await readCount(`${theme} mat-select`);
202	
203			// (candidate B) The huePrimary mat-select, now revealed. Open it and pick a
204			// hue far from the 500 default; the contrast threshold moves and the
205			// contrast custom properties shift on save.
206			out['hue-select-open'] = await clickIfPresent(`${theme} mat-select`);
207			await wait(800);
208			out['overlay-option-count'] = await readCount('.cdk-overlay-container mat-option');
209			out['hue-option-click'] = await clickIfPresent(
210				'.cdk-overlay-container mat-option:first-of-type',
211			);
212			await wait(600);
213			out['palette-after-hue-pick-preSave'] = await readPalette();
214			out['hue-save'] = await clickIfPresent(`${theme} .submit-button`);
215			await wait(1_800);
216			out['palette-after-hue-save'] = await readPalette();
217	
218			// (d.3) Keyboard shortcuts. `w` (goToWorkView) and `b` (toggleBacklog),
219			// measured for their observable DOM effect in this state (the box page
220			// exposes no route reader, so the work view host tag and the backlog/split
221			// surfaces are the measurement).
222			out['work-view-count-before-w'] = await readCount('work-view');
223			await page.press('body', 'w');
224			await wait(1_000);
225			out['work-view-count-after-w'] = await readCount('work-view');
226			out['split-count-before-b'] = await readCount('split');
227			out['backlog-count-before-b'] = await readCount('backlog');
228			await page.press('body', 'b');
229			await wait(1_000);
230			out['work-view-count-after-b'] = await readCount('work-view');
231			out['split-count-after-b'] = await readCount('split');
232			out['backlog-count-after-b'] = await readCount('backlog');
233	
234			await context.receipt.capture('theme-calibration-complete');
235		});
236		let status = 'unknown';
237		let failure = '';
238		let receiptPath = '';
239		try {
240			const result = await runBoxes({
241				root: laneRoot,
242				boxes: [
243					{
244						file: join(laneRoot, 'versionless-runtime.box.ts'),
245						relativeFile: 'versionless-runtime.box.ts',
246						exportName: 'default',
247						box: definition,
248					},
249				],
250				receiptDir,
251				assertionTimeoutMs: 4_000,
252				fileSystem: witnessNodeFileSystem,
253				browser: host.browser,
254				headless: true,
255			});
256			status = result.status;
257			failure = result.boxes[0]?.error?.message ?? '';
258			receiptPath = result.receiptPath;
259		} finally {
260			await staticServer.close();
261		}
262		process.stdout.write(`${canonicalize({ lane, status, failure, receiptPath, out })}\n`);
263	}
264	
265	export async function main(args = process.argv.slice(2)): Promise<void> {
266		const lane = args[0];
267		if (lane !== 'baseline' && lane !== 'migrated')
268			throw new Error('Super Productivity theme calibration requires a lane: baseline or migrated');
269		await calibrateAngularSuperProductivityTheme(lane);
270	}
271	
272	if (basename(process.argv[1] ?? '') === 'angular-super-productivity-theme-calibrate-run.ts')
273		main().catch((error: unknown) => {
274			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
275			process.exitCode = 1;
276		});
