 * The rendered-style projection that participates in the parity digest: the
 * probes the lanes must agree on, in full, plus the LABELS of the ones the

}

/**
 * Leg (c): starting and stopping a task's timer through the header play button.
 * The anchor is the icon flip on that control — a different icon after the timer
 * starts than before, and the before-icon back again after it stops — plus the
 * current task the start sets and the stop clears. The dropped play-indicator
 * and time-value sub-rules are recorded as non-claims on the re-anchor constant.
 */
function assertTimeTracking(
	journey: WitnessAngularSuperProductivityJourney | undefined,
	label: string,
): void {
	const tracking = journey?.timeTracking;
	if (
		tracking === undefined ||
		tracking.state !== 'measured-task-time-tracking' ||
		tracking.control !== WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TIME_TRACKING_REANCHOR.control ||
		tracking.iconBeforeStart.length === 0 ||
		tracking.iconAfterStart.length === 0 ||
		tracking.iconAfterStop.length === 0 ||
		// The flip: start shows a different icon than rest.
		tracking.iconBeforeStart === tracking.iconAfterStart ||
		// The round trip: stopping returns the control to its resting icon.
		tracking.iconAfterStop !== tracking.iconBeforeStart ||
		// Starting set exactly one current task; stopping cleared it.
		tracking.currentTasksOnStart !== 1 ||
		tracking.currentTasksOnStop !== 0
	)
		throw new Error(`Angular Super Productivity time-tracking evidence differs: ${label}`);
}

/**
 * Leg (d): the settings-change, checked as three rules rather than against pinned
 * literals. The project-switch grew the side-nav list by exactly one and the
 * switch flipped the current-project title to the created project; the driven
 * `huePrimary` mat-select change shifted the measured contrast style var (the
 * rgb it lands on is per-lane and is not held equal here — that is the declared
 * lane difference on {@link WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SETTINGS}); and
 * the `w` shortcut brought the work view. The unprovable color-input path is not
 * claimed at all, per u20c2l.
 */
function assertSettings(
	journey: WitnessAngularSuperProductivityJourney | undefined,
	label: string,
): void {
	const settings = journey?.settings;
	if (
		settings === undefined ||
		settings.state !== 'measured-settings-change' ||
		// The project-switch spine.
		settings.projectSwitch.control.length === 0 ||
		settings.projectSwitch.dialog.length === 0 ||
		settings.projectSwitch.titleControl.length === 0 ||
		settings.projectSwitch.switchControl.length === 0 ||
		settings.projectSwitch.newProjectTitle.length === 0 ||
		settings.projectSwitch.currentTitleBefore.length === 0 ||
		// The create grew the side-nav project list by exactly one.
		settings.projectSwitch.projectCountAfter !== settings.projectSwitch.projectCountBefore + 1 ||
		// The switch flipped the current-project title to the project the create
		// named, so the title changed and it changed to the new project.
		settings.projectSwitch.currentTitleBefore === settings.projectSwitch.currentTitleAfter ||
		settings.projectSwitch.currentTitleAfter !== settings.projectSwitch.newProjectTitle ||
		// The driven theme control.
		settings.theme.control.length === 0 ||
		settings.theme.autoContrastControl.length === 0 ||
		settings.theme.styleVar.length === 0 ||
		settings.theme.styleValueBefore.length === 0 ||
		settings.theme.styleValueAfter.length === 0 ||
		// The driven change shifted the measured style var: before differs from
		// after. The value itself is a declared lane difference and not checked
		// equal across lanes.
		settings.theme.styleValueBefore === settings.theme.styleValueAfter ||
		// The shortcut brought the work view.
		settings.shortcut.key.length === 0 ||
		settings.shortcut.hostTag.length === 0 ||
		settings.shortcut.hostTagPresentAfter < 1
	)
		throw new Error(`Angular Super Productivity settings evidence differs: ${label}`);
}

/**
 * Every recorded route is a hash route naming one of the application's own
 * declared routes, or a parameterised child of one. The sequence itself belongs
 * to the journey and is required to be identical across the four runs by the
 * behavior digest.
 */
function assertRouteShape(routes: string[], label: string): void {
	const shape = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE;
	const known = shape.known as readonly string[];
	const parameterised = shape.parameterised as readonly string[];
	if (!Array.isArray(routes) || routes.length === 0)
		throw new Error(`Angular Super Productivity route shape differs: ${label}`);
	for (const route of routes) {
		const hash = route.startsWith('/#/') ? route.slice(1) : route;
		if (!hash.startsWith(shape.prefix))
			throw new Error(`Angular Super Productivity route is not a hash route: ${route}`);
		const [named = ''] = hash.slice(1).split('?');
		const parameterisedParent = parameterised.find((parent) =>
			named.startsWith(`${parent}/`),
		);
		if (!known.includes(named) && parameterisedParent === undefined)
			throw new Error(`Angular Super Productivity route is not a declared route: ${route}`);
	}
}

/**
 * The service-worker record, held to the non-masking discipline.
 *
 * Nothing here is asserted away. The three checkpoints must be present in
 * journey order; the registration must name the script the application asked
 * for at every one of them; the trace may not be empty, because a browser that
 * registered a worker recorded doing so; and every event in it must name either
 * the scope the registration took or the script it ran. The worker files the
 * build shipped are read before and after the run and must be byte-identical,
 * because a served tree a worker rewrote is not the tree the lane was bound to.
 *
 * What is NOT asserted is the settled state itself — which version is active,
 * which caches exist, whether the page is controlled at a given checkpoint.
 * Those are measurements, they travel in the parity digest so the two lanes
 * cannot disagree about them silently, and they are pinned when this proof is
 * published.
 *
