	const declared = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER;
	const names = (
		events: WitnessServiceWorkerTelemetry['workerEvents'],
	): boolean =>
		events.length !== 0 &&
